    add('gatk.mt.filter','FilterMutectCalls · mitochondrial mode','Variants',[P('variants','VCF|BGZIP_VCF|INDEXED_VCF'),P('statistics','REPORT'),P('reference','FASTA')],[P('variants','VCF')],'Filter the matching mitochondrial calls/stats in mitochondrial mode. This does not replace contamination, artifact-site review or assay validation.',[],**common)
    add('mito.liftover','Lift shifted mtDNA calls back','Adapters',[P('variants','VCF|BGZIP_VCF|INDEXED_VCF'),P('chain','CHAIN'),P('reference','FASTA')],[P('variants','VCF'),P('rejected','VCF')],'Picard/GATK LiftoverVcf using the exact rotated-to-original chain and original mitochondrial reference. Rejected alleles are preserved.',[],**common)
    add('mito.extract','Mitochondrial + nuclear candidate extraction','Adapters',[P('alignment','INDEXED_BAM'),P('regions','BED')],[P('alignment','BAM')],'Fetch declared mitochondrial/NUMT candidate intervals and their read mates from whole-genome alignments. Candidate intervals must be explicit and assembly-compatible; no automatic NUMT diagnosis.',[],executable='samtools',image='quay.io/biocontainers/samtools:1.21--h50ea8bc_0',docs='https://www.htslib.org/doc/samtools-view.html')
    add('mito.realign','Realign candidate reads to mtDNA reference','Alignment',[P('alignment','BAM|INDEXED_BAM'),P('reference','FASTA')],[P('alignment','INDEXED_BAM')],'Name-collate and retain candidate reads, then BWA-MEM2 smart-pair alignment to the selected original/rotated reference, sorting and indexing. Requires a combined BWA-MEM2/SAMtools worker.',[param('sample_id','Read-group sample ID','SAMPLE')],executable='bwa-mem2',image=None,docs='https://github.com/bwa-mem2/bwa-mem2')
